//refAssemblies: TCAdmin.Web.Shared.dll, System.Net.NetworkInformation.dll, System.Net.Primitives.dll
using System;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Necesse has no server-browser query (players join by address) and its game protocol has no status request, so a
// probe on the game port would be handled as a connecting client. The query runs on the monitor of the server that
// hosts the service, so it checks that the game's UDP port is bound on this machine (silent, no console noise).
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
// Necesse uses one UDP port; the panel's query port is ignored so a changed QueryPort cannot break the status.
int port = ThisService.GamePort;

try
{
    IPAddress.TryParse(address, out var ip);
    // Java binds dual-stack sockets: on Linux the game socket is listed as ::ffff:<address> (an IPv4-mapped address).
    var listening = IPGlobalProperties.GetIPGlobalProperties().GetActiveUdpListeners()
        .Select(l => new IPEndPoint(l.Address.IsIPv4MappedToIPv6 ? l.Address.MapToIPv4() : l.Address, l.Port))
        .Any(l => l.Port == port && (ip == null || l.Address.Equals(ip) || l.Address.Equals(IPAddress.Any) || l.Address.Equals(IPAddress.IPv6Any)));
    Globals.ReturnValue = listening
        ? new GameQueryResponse
        {
            Success = true,
            Status = "online",
            Protocol = "custom_script",
            Address = address,
            Hostname = $"{address}:{port}",
            Name = ThisService.Name,
            GameType = "Necesse",
            Map = "",
            NumPlayers = 0,
            MaxPlayers = ThisService.Slots,
            NumSpectators = 0,
            MaxSpectators = 0,
            Retries = 0
        }
        : GameQueryResponse.DefaultOfflineResponse(address, "custom_script", $"Nothing is listening on {address}:{port} (UDP).");
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Necesse servers load every mod .jar in the mods folder of their data folder (-localdir = the service root) when
// they start. Copy the .jar of this Workshop item to mods/workshop-<id>.jar; the server loads it at its next start.
string fileId = Convert.ToString(Dynamic.FileId).Trim();
if (!Regex.IsMatch(fileId, "^[0-9]+$")) throw new Exception("Unexpected Workshop id: " + fileId);
string installPath = Convert.ToString(Dynamic.InstallPath);
string root = (string)ThisService.RootDirectory;

if (string.IsNullOrEmpty(installPath) || !Directory.Exists(installPath) || IsLink(installPath))
    throw new Exception("Nothing was downloaded for Workshop item " + fileId + ".");
// The script runs as the monitor: never follow a link the service user could have planted in the download.
var walk = new EnumerationOptions { RecurseSubdirectories = true, AttributesToSkip = FileAttributes.ReparsePoint, IgnoreInaccessible = true };
var jars = Directory.EnumerateFiles(installPath, "*.jar", walk)
    .Where(f => !IsLink(f))
    .OrderBy(f => f, StringComparer.Ordinal).ToList();
if (jars.Count == 0) throw new Exception("Workshop item " + fileId + " has no mod file (.jar). Necesse servers load .jar mods only.");

string mods = ModsDir(root);
var locked = new List<string>();
RemoveCopies(mods, fileId, locked);
if (locked.Count > 0) throw new Exception("The running server uses " + string.Join(", ", locked) + ": stop the server and install the mod again.");
for (int i = 0; i < jars.Count; i++)
{
    string name = "workshop-" + fileId + (i == 0 ? "" : "-" + i) + ".jar";
    string target = Path.Combine(mods, name);
    File.Copy(jars[i], target, false);
    if (!System.OperatingSystem.IsWindows()) Globals.OperatingSystem.SetFileOwnerAutoDetect(target);
    ScriptConsole.WriteLine((object)("Copied " + Path.GetFileName(jars[i]) + " to mods/" + name + "."));
}
ScriptConsole.WriteLine((object)"The server loads the mod the next time it starts. Players need the same mod (the game offers to download it when they join).");

// A symbolic link or junction (reparse point on Windows).
bool IsLink(string path)
{
    // LinkTarget also sees a dangling link (File.Exists is false for one) and Windows junctions.
    var info = new FileInfo(path);
    if (info.LinkTarget != null) return true;
    if (!info.Exists && !Directory.Exists(path)) return false;
    return (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0;
}

// <root>/mods, created when missing. The script runs as the monitor, so the folder must be a real folder inside the
// service root: a link planted by the service user would make the monitor write or delete files elsewhere.
string ModsDir(string serviceRoot)
{
    if (IsLink(serviceRoot)) throw new Exception("The service folder is a link; refusing to change mods.");
    string dir = Path.Combine(serviceRoot, "mods");
    if (!Directory.Exists(dir) && File.Exists(dir)) throw new Exception("mods is a file, not a folder.");
    if (!Directory.Exists(dir))
    {
        Directory.CreateDirectory(dir);
        if (!System.OperatingSystem.IsWindows()) Globals.OperatingSystem.SetFileOwnerAutoDetect(dir);
    }
    if (IsLink(dir)) throw new Exception("The mods folder is a link; refusing to change it. Delete the link and try again.");
    return dir;
}

// Deletes mods/workshop-<id>.jar and mods/workshop-<id>-<n>.jar. Returns the number deleted; a file the running
// server keeps open (Windows) is added to locked.
int RemoveCopies(string modsDir, string id, List<string> locked)
{
    var name = new Regex("^workshop-" + id + "(-[0-9]+)?" + Regex.Escape(".jar") + "$", RegexOptions.IgnoreCase);
    int count = 0;
    foreach (var f in Directory.EnumerateFileSystemEntries(modsDir).Where(f => name.IsMatch(Path.GetFileName(f))).ToList())
    {
        if (Directory.Exists(f)) continue;
        try { File.Delete(f); count++; }
        catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException) { locked.Add(Path.GetFileName(f)); }
    }
    return count;
}

