using System;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Linux: Steam downloads can lose the executable bit. Make the bundled Java runtime (jre/bin/*, jre/lib/jspawnhelper)
// executable. The script runs as root in a folder the service user owns, so it never follows a symbolic link: a
// link planted there would make root change the mode of a file elsewhere.
var root = (string)ThisService.RootDirectory;
if (System.OperatingSystem.IsLinux())
{
    var jre = Path.Combine(root, "jre");
    var bin = Path.Combine(jre, "bin");
    if (IsLink(root) || IsLink(jre) || IsLink(bin) || IsLink(Path.Combine(jre, "lib")))
        throw new Exception("The Java runtime folder (jre) contains a symbolic link; reinstall the server.");
    var files = Directory.Exists(bin) ? Directory.EnumerateFiles(bin).ToList() : new System.Collections.Generic.List<string>();
    var helper = Path.Combine(jre, "lib", "jspawnhelper");
    if (File.Exists(helper)) files.Add(helper);
    if (files.Count == 0) throw new Exception("jre/bin is missing; reinstall the server.");
    var exec = UnixFileMode.UserExecute | UnixFileMode.GroupExecute | UnixFileMode.OtherExecute;
    int changed = 0;
    foreach (var f in files)
    {
        if (IsLink(f)) continue;
        var mode = File.GetUnixFileMode(f);
        if ((mode & exec) == exec) continue;
        File.SetUnixFileMode(f, mode | exec);
        changed++;
    }
    if (changed > 0) ScriptConsole.WriteLine((object)("Made " + changed + " Java runtime file(s) executable."));
}

